// Package web serves the embedded React board and mounts the JSON API on a
// loopback listener.
package web

import "embed"

// The underscore on _ui keeps node_modules out of `go build ./...` (the go
// tool skips "_"-prefixed dirs) and the all: prefix is what makes the embed
// pattern descend into it anyway. _ui/dist is generated by `npm run build`;
// a placeholder index.html keeps a clean clone compiling.
//
//go:embed all:_ui/dist
var assets embed.FS
